using Ome.Engine.Model;
using Ome.Engine.Modding;
using Ome.Engine.Sys4;
using Ome.Mods.Launch;
using Ome.Mods.Linking;
using Ome.Mods.Manifest;
using Ome.Mods.Packages;
using Ome.Script.Abi;

/// <summary>
/// Milestone 3 of docs/superpowers/specs/2026-11-10-lua-scripting-design.md, its first part: the base mods (§9.1).
/// The engine ships one per game with a registry, generated by tools/base_mod_build.py, and mounts it only when an
/// enabled mod requires it; a package with a layout is a base mod, and its layout is checked when it opens.
/// </summary>
public sealed class BaseModTests : IDisposable
{
    private readonly string _root = Path.Combine(Path.GetTempPath(), "ome-basemod-" + Guid.NewGuid().ToString("N"));

    public void Dispose()
    {
        if (Directory.Exists(_root)) Directory.Delete(_root, recursive: true);
    }

    private const string Layout = """
        {
         "layout": 1,
         "profile": "himegari",
         "globals": [
          {"name": "current_unit_id", "bank": "G", "address": "0x10", "dims": []},
          {"name": "unit_levels", "bank": "G", "address": "0x100", "dims": [100], "aliases": ["unit_current_levels"]},
          {"name": "unit_conditions", "bank": "G", "address": "0x200", "dims": [null, 30], "columns": {"charm": 6}},
          {"name": "unit_names", "bank": "GS", "address": "0x0", "dims": [1000, 2]}
         ]
        }
        """;

    private string Folder(string id, string manifest, IReadOnlyDictionary<string, string>? files = null)
    {
        string folder = Path.Combine(_root, id);
        Directory.CreateDirectory(folder);
        File.WriteAllText(Path.Combine(folder, "manifest.toml"), manifest);
        foreach (var (path, text) in files ?? new Dictionary<string, string>())
        {
            string file = Path.Combine(folder, path.Replace('/', Path.DirectorySeparatorChar));
            Directory.CreateDirectory(Path.GetDirectoryName(file)!);
            File.WriteAllText(file, text);
        }
        return folder;
    }

    private static string Manifest(string id, string version = "1.0.0", string game = "[game]\nprofile = \"himegari\"\ntarget = \"extended\"\n",
                                   string lua = "[lua]\napi = 1\ncapabilities = [\"vm\"]\n", string extra = "")
        => $"omp = 3\nid = \"{id}\"\nname = \"{id}\"\nversion = \"{version}\"\n{game}{lua}{extra}";

    private const string RequiresBase = "[[requires]]\nid = \"himegari-base\"\nversion = \">=1.0, <2\"\n";

    // ------------------------------------------------------------------------------------------------ the shipped ones

    [Fact]
    public void TheEngineShipsABaseModForEachGameWithARegistryAndItIsTheRepositorysFolder()
    {
        // The base mods, and ome-records, the library they apply record tables with (data patches spec §6.4).
        Assert.Equal(["himegari-base", "kamidori-base", "ome-records"], ShippedPackages.Ids);
        foreach (string id in ShippedPackages.Ids.Where(id => id.EndsWith("-base", StringComparison.Ordinal)))
        {
            using ModPackage shipped = ShippedPackages.Open(id)!;
            using ModPackage folder = ModPackage.Open(Path.Combine(Paths.Repo, "mods", id));
            Assert.Equal(id, shipped.Id);
            Assert.Equal(ShippedPackages.LocationOf(id), shipped.Location);
            Assert.Equal(id[..^"-base".Length], shipped.Manifest.Profile);
            Assert.Equal(shipped.Manifest.Profile, shipped.BaseLayout!.Profile);
            Assert.NotNull(shipped.BasePoints);
            Assert.True(shipped.Manifest.Lua!.HasVm);
            // The embedded copy is the folder as the repository holds it.
            Assert.Equal(folder.Hash, shipped.Hash);
            // Each requires the library, which the engine ships too.
            Assert.Contains(shipped.Manifest.Requires, requirement => requirement.Id == "ome-records");
            // Each accepts its game's record tables as data files, applied at the boot's data.layered and at each
            // stage's stage.loaded (data patches spec §6.2), by the same handlers.
            string game = shipped.Manifest.Profile!;
            Assert.Equal(ModManifest.DataOmpVersion, shipped.Manifest.OmpVersion);
            ModKind kind = Assert.Single(shipped.Manifest.Accepts);
            Assert.Equal($"{game}.tables", kind.Kind);
            Assert.Equal([($"{game}.data.layered", "tables.lua:apply_boot"), ($"{game}.stage.loaded", "tables.lua:apply_stage")],
                         kind.At.Select(at => (at.Event, at.Handler.ToString())));
            Assert.Empty(shipped.Manifest.Data);
        }
        using (ModPackage library = ShippedPackages.Open("ome-records")!)
        using (ModPackage folder = ModPackage.Open(Path.Combine(Paths.Repo, "mods", "ome-records")))
        {
            // A library: no game, no layout, no capability.
            Assert.Null(library.Manifest.Profile);
            Assert.Null(library.BaseLayout);
            Assert.False(library.Manifest.Lua!.HasVm);
            Assert.Equal(folder.Hash, library.Hash);
        }
        Assert.Null(ShippedPackages.Open("other-base"));
    }

    [Fact]
    public void TheLayoutsNameTheRegistriesCells()
    {
        using ModPackage himegari = ShippedPackages.Open("himegari-base")!;
        GameLayout layout = himegari.BaseLayout!;
        Assert.True(layout.TryGet("unit_current_levels", out LayoutGlobal levels));
        Assert.Equal((CellKind.Integer, 0x6930), (levels.Kind, levels.Address));
        Assert.Equal([100], levels.Dimensions);
        Assert.True(layout.TryGet("current_unit_id", out LayoutGlobal unit) && unit.IsScalar);
        Assert.True(layout.TryGet("save_slot_chapter_titles", out LayoutGlobal titles));
        Assert.Equal((CellKind.String, 0x0), (titles.Kind, titles.Address));
        Assert.True(himegari.BasePoints!.TryGet("himegari.experience.after_calculation", out _));

        using ModPackage kamidori = ShippedPackages.Open("kamidori-base")!;
        Assert.True(kamidori.BaseLayout!.TryGet("unit_condition_levels", out LayoutGlobal conditions));
        Assert.Equal([null, 30], conditions.Dimensions);   // int[unit][30]: the row count is open
        Assert.Equal(6, conditions.Columns["charm"]);
        Assert.True(kamidori.BaseLayout.TryGet("town_site_cursor_links", out LayoutGlobal links));
        Assert.Equal([30, 4], links.Dimensions);           // int[30x4]
    }

    // ---------------------------------------------------------------------------------------------- mounting on demand

    [Fact]
    public void DiscoveryMountsTheBaseModOnlyWhenAnEnabledModRequiresIt()
    {
        string mods = Path.Combine(_root, "mods");
        Directory.CreateDirectory(mods);
        Directory.Move(Folder("plain", Manifest("plain")), Path.Combine(mods, "plain"));
        var report = new ModLinkReport();
        ModDiscovery without = ModLaunch.Discover(mods, [], report);
        Assert.Equal(["plain"], without.Packages.Select(package => package.Id));

        Directory.Move(Folder("needs-base", Manifest("needs-base", extra: RequiresBase)), Path.Combine(mods, "needs-base"));
        report = new ModLinkReport();
        ModDiscovery with = ModLaunch.Discover(mods, [], report);
        ModPackage shipped = Assert.Single(with.Packages, package => package.Id == "himegari-base");
        Assert.Equal(ShippedPackages.LocationOf("himegari-base"), shipped.Location);
        Assert.Contains(report.Lines, line => line.Message.Contains("the engine's own himegari-base 1.1.0 is mounted: needs-base requires it"));
        // The resolver finds the requirement met, and the base mod loads before the mod that requires it.
        var order = new ModLinkReport();
        IReadOnlyList<ModPackage> resolved = StackResolver.Resolve(with.Packages, SyntheticBase(), with.UserOrder, order);
        Assert.False(order.Stops, order.Render());
        Assert.True(resolved.ToList().FindIndex(package => package.Id == "himegari-base")
                    < resolved.ToList().FindIndex(package => package.Id == "needs-base"));

        // A disabled mod requires nothing.
        File.WriteAllText(Path.Combine(mods, ModLaunch.LoadOrderFile), "-needs-base\n");
        Assert.DoesNotContain(ModLaunch.Discover(mods, [], new ModLinkReport()).Packages, package => package.Id == "himegari-base");
    }

    [Fact]
    public void AnInstalledBaseModIsUsedInsteadOfTheEnginesOwn()
    {
        string mods = Path.Combine(_root, "mods");
        Directory.CreateDirectory(mods);
        Directory.Move(Folder("needs-base", Manifest("needs-base", extra: RequiresBase)), Path.Combine(mods, "needs-base"));
        string installed = Path.Combine(mods, "himegari-base");
        Directory.Move(Folder("himegari-base", Manifest("himegari-base", "1.2.0"), new Dictionary<string, string> { ["layout/globals.json"] = Layout }),
                  installed);
        var report = new ModLinkReport();
        ModDiscovery discovery = ModLaunch.Discover(mods, [], report);
        ModPackage used = Assert.Single(discovery.Packages, package => package.Id == "himegari-base");
        Assert.Equal("1.2.0", used.Manifest.Version.ToString());
        Assert.Contains(report.Lines, line => line.Message.Contains("is used instead of the engine's own himegari-base"));
    }

    // ----------------------------------------------------------------------------------------- a layout and its rules

    [Fact]
    public void APackageWithALayoutIsABaseModAndItsLayoutIsReadWhenItOpens()
    {
        using ModPackage package = ModPackage.Open(Folder("himegari-base", Manifest("himegari-base"),
            new Dictionary<string, string> { ["layout/globals.json"] = Layout, ["layout/exports.txt"] = "major = 1\n" }));
        GameLayout layout = package.BaseLayout!;
        Assert.Null(package.BasePoints);
        Assert.Equal(["current_unit_id", "unit_conditions", "unit_levels", "unit_names"], layout.Globals.Select(global => global.Name));
        // An alias and the name it stands for are one name.
        Assert.True(layout.TryGet("unit_current_levels", out LayoutGlobal alias));
        Assert.True(layout.TryGet("unit_levels", out LayoutGlobal name));
        Assert.Same(name, alias);
        Assert.Contains("unit_current_levels", layout.Names);

        using ModPackage plain = ModPackage.Open(Folder("plain", Manifest("plain")));
        Assert.Null(plain.BaseLayout);
    }

    public static TheoryData<string, string, string> RefusedLayouts => new()
    {
        { "without vm", Manifest("b", lua: "[lua]\napi = 1\n"), "needs [lua] capabilities = [\"vm\"]" },
        { "without Lua", Manifest("b", lua: ""), "needs [lua] capabilities = [\"vm\"]" },
        { "another game's", Manifest("b", game: "[game]\nprofile = \"kamidori\"\ntarget = \"extended\"\n"),
          "the layout is himegari's, and the package targets kamidori" },
        { "a library", Manifest("b", game: "", lua: "[lua]\napi = 1\n"), "a package without [game] carries no layout" },
        { "an earlier format", "omp = 2\nid = \"b\"\nname = \"b\"\nversion = \"1.0.0\"\n[game]\nprofile = \"himegari\"\ntarget = \"native\"\n",
          "layout/ needs omp = 3" },
    };

    [Theory]
    [MemberData(nameof(RefusedLayouts))]
    public void ALayoutNeedsVmAGameAndItsOwnProfile(string why, string manifest, string message)
    {
        Assert.NotNull(why);
        string folder = Folder("b", manifest, new Dictionary<string, string> { ["layout/globals.json"] = Layout });
        Assert.Contains(message, Assert.Throws<ModPackageException>(() => ModPackage.Open(folder)).Message);
    }

    [Theory]
    [InlineData("layout/globals.json", "{ \"layout\": 2, \"profile\": \"himegari\", \"globals\": [] }", "its format is 2; this engine reads 1")]
    [InlineData("layout/globals.json", "{ \"layout\": 1, \"profile\": \"himegari\", \"globals\": [{\"name\": \"a\", \"bank\": \"G\", \"address\": \"0x0\", \"dims\": [4, null]}] }",
                "global a: a dimension is null")]
    [InlineData("layout/globals.json", "{ \"layout\": 1, \"profile\": \"himegari\", \"globals\": [{\"name\": \"a\", \"bank\": \"G\", \"address\": \"0x0\", \"dims\": [4], \"columns\": {\"x\": 4}}] }",
                "global a: column x = 4 is not a name and an index of its last dimension")]
    [InlineData("layout/globals.json", "{ \"layout\": 1, \"profile\": \"himegari\", \"globals\": [{\"name\": \"a\", \"bank\": \"G\", \"address\": \"0x0\", \"dims\": []}, {\"name\": \"b\", \"bank\": \"G\", \"address\": \"0x1\", \"dims\": [], \"aliases\": [\"a\"]}] }",
                "'a' names both a and b")]
    [InlineData("layout/globals.json", "{ \"layout\": 1, \"profile\": \"himegari\", \"globals\": [{\"name\": \"a\", \"bank\": \"GP\", \"address\": \"0x0\", \"dims\": []}] }",
                "global a: bank GP is not G, GF or GS")]
    [InlineData("layout/notes.txt", "", "layout/ holds globals.json, points.json and exports.txt")]
    [InlineData("layout/points.json", "{ \"profile\": \"himegari\", \"points\": [] }", "a base mod's layout needs layout/globals.json")]
    public void ALayoutThatIsNotOneIsRefusedWhenThePackageOpens(string path, string text, string message)
    {
        string folder = Folder("b", Manifest("b"), new Dictionary<string, string> { [path] = text });
        Assert.Contains(message, Assert.Throws<ModPackageException>(() => ModPackage.Open(folder)).Message);
    }

    private static readonly OpcodeTable Table = OpcodeTableJson.Load(Paths.OpcodesJson, "SYS4422");
    private static readonly OpcodeContracts Contracts = OpcodeContracts.Load(Paths.OpcodesJson);

    private static ModLinkBase SyntheticBase() => new()
    {
        Profile = "himegari",
        CatalogFingerprint = "sha256:" + new string('1', 64),
        ReadScript = _ => null,
        Table = Table,
        Contracts = Contracts,
        Intrinsics = new IntrinsicCatalog(Table, Contracts),
        CatalogTitle = "TEST",
        ToolchainStamp = "test",
    };
}
